template:
struct Lru {
    order: Vec<String>,
}

impl Lru {
    fn touch(&mut self, key: &str) {
        if let Some(pos) = self.order.iter().position(|k| k == key) {
            let k = self.order.{{0}}(pos);
            self.order.{{1}}(k);
        }
    }
}

fn main() {
    let mut c = Lru { order: vec!["a".to_string(), "b".to_string()] };
    c.touch("a");
    println!("{:?}", c.order);
}
